  "A_valid": "无效",
  "A_restitution": "122816.00",
  "A_guarantee": "主合同无效，丁的保证合同亦无效；本次保证给付请求不支持，且不审查未被请求的无效后过错赔偿。",
  "B_initial_principal": "187030.00",
  "B_protected_total": "203220.81",
  "B_guarantee": "戊承担有效的全额连带责任保证；甲已在保证期间内依法行权，撤诉不消灭该效果。内部50%分担约定不限制对甲的责任，亦不存在因甲未向庚及时行权而部分免责的情形。",
  "C_outstanding_principal": "152860.88",
  "C_outstanding_interest": "1415.53",
  "C_outstanding_expenses": "0.00",
  "C_guarantee": "己原为有效的一般保证，甲在保证期间届满前重新起诉乙，原保证责任未因期间经过消灭；但S14将全部C余额转移给辛，未经己书面同意，己对该全部债务不再承担保证责任，本次立即给付请求不支持。",
  "borrower_total": "326036.81",
  "B_second_guarantee": "庚承担有效的全额连带责任保证；2023-07-06已在保证期间内收到甲的完整给付请求。对剩余B债务203220.81元的立即给付请求可获支持，与乙、戊的同一债务不得重复受偿。",
  "B_joint_payment_limit": "203220.81",
  "C_third_party_type": "经甲同意的全部免责债务承担，即C剩余债务全部转移给辛、乙退出；不是保证，也不是与乙并存的债务加入。辛承担直接付款义务。",
  "C_third_party_payment_limit": "154276.41",
  "C_original_borrower_liability": "0.00",
  "basis": {
    "A": {
      "facts": ["dossier.md S01", "dossier.md S02", "dossier.md S12"],
      "rules": [
        {"source_id": "lending-2020-12", "provision": "13、31"},
        {"source_id": "civil-code-2020", "provision": "157、682"}
      ],
      "explanation": "A于2022年成立，已证实套取银行信贷资金转贷，适用规则不要求另具高利或乙事先知情。按实际取得财产返还，重复收据不构成第二次交付。",
      "calculation": "143123.00－20307.00＝122816.00元；未交付票面差额和无效后赔偿不在最终请求范围内。"
    },
    "B_balance": {
      "facts": ["dossier.md S03", "dossier.md S04", "dossier.md S05", "dossier.md S13"],
      "rules": [
        {"source_id": "civil-code-2020", "provision": "670、679、680"},
        {"source_id": "lending-2020-12", "provision": "25、26、27、28"}
      ],
      "explanation": "预扣利息12551.00元不计入初始本金。后三张借据没有新增交付或债务更新，须从实际本金逐次重算可保护结息，不能直接采纳纸面金额。约定年利率13.2%低于合同成立时LPR四倍14.8%。",
      "calculation": [
        "初始本金＝199581.00－12551.00＝187030.00元。",
        "四段日数依次为175、103、84、204日，共566日；每段适用P下一期＝P本期×(1＋13.2%×日数/365)。全程保留精度。",
        "2022-07-06、2022-10-17、2023-01-09重算本金分别显示为198866.69、206274.34、212540.56元；截至2023-08-01、不计当日利息的滚算本息为228220.81元。",
        "第27条总额上限＝187030×(1＋14.8%×566/365)＝229953.64元，未触及该上限。",
        "SP-01到账后余额＝228220.812766…－25000.00＝203220.81元。"
      ]
    },
    "B_guarantors": {
      "facts": ["dossier.md S06", "dossier.md S12"],
      "rules": [
        {"source_id": "civil-code-2020", "provision": "688、691、692、693、695"},
        {"source_id": "guarantee-2020", "provision": "13、25、29、31、32、34"}
      ],
      "explanation": [
        "戊正文表示无条件清偿、无须先向乙追索，且共同正文明确戊、庚各以连带责任保证覆盖全部B债务，故不是一般保证或对外各半保证。",
        "“直至本息全部还清”属于保证期间约定不明。两人均未书面同意展期，保证期间仍以原到期日2023-01-12起算六个月，至2023-07-12届满。",
        "甲对戊的起诉状副本于2023-07-07送达，虽2023-07-09撤诉，依第31条仍属期间内行权。甲对庚的独立完整请求于2023-07-06到达，同样及时；不是以对戊行权替代对庚行权。",
        "内部各50%约定仅规范相互追偿。甲没有因漏向庚行权而损害戊的追偿权，第29条部分免责条件不成立。两人对最终B余额均承担全额连带保证责任，但不得重复受偿。"
      ]
    },
    "C_balance": {
      "facts": ["dossier.md S07", "dossier.md S08", "dossier.md S09", "dossier.md S11"],
      "rules": [
        {"source_id": "lending-2015", "provision": "26"},
        {"source_id": "lending-2020-12", "provision": "25、28、31"},
        {"source_id": "civil-code-2020", "provision": "561"}
      ],
      "explanation": [
        "依甲明确请求，成立日至2020-08-19适用旧解释，约定23.5%未超过24%；2020-08-20起按起诉时题设LPR四倍，即3.25%×4＝13%保护，逾期亦按13%。",
        "原合同约定费用、合法利息、本金的清偿顺序；仅T-02经双方补充约定先还本金，其26978.00元全部冲本金。其他单方“还本金”备注不改变原约定。",
        "T-01截图、收据与主表系同一交易，只计一次。X-01未执行、未到账，不构成清偿。T系列实际付款合计213080.00元。",
        "按未偿本金、实际自然日/365单利计算，未付利息不生息；付款日不再对被偿还本金计息。下列中间余额仅为取分展示，计算未逐次取分。"
      ],
      "day_counts": [
        "2019-02-07至2019-04-18：70日，23.5%。",
        "2019-04-18至2019-08-23：127日，23.5%。",
        "2019-08-23至2020-02-14：175日，23.5%。",
        "2020-02-14至2020-08-20：188日，23.5%；2020-08-20至2020-09-21：32日，13%。",
        "2020-09-21至2021-04-11：202日；至下一付款日2022-06-06：421日；至下一付款日2023-07-06：395日；此后至2023-08-01：26日，均为13%。"
      ],
      "payment_ledger": [
        {"payment": "T-01", "principal_after": "214489.15", "interest_after": "0.00", "expenses_after": "0.00"},
        {"payment": "T-02", "principal_after": "187511.15", "interest_after": "17538.16", "expenses_after": "0.00"},
        {"payment": "T-03", "principal_after": "187511.15", "interest_after": "9956.27", "expenses_after": "0.00"},
        {"payment": "T-04", "principal_after": "187511.15", "interest_after": "4349.94", "expenses_after": "0.00"},
        {"payment": "T-05", "principal_after": "173180.62", "interest_after": "0.00", "expenses_after": "0.00"},
        {"payment": "T-06", "principal_after": "165246.23", "interest_after": "0.00", "expenses_after": "0.00"},
        {"payment": "T-07", "principal_after": "152860.88", "interest_after": "0.00", "expenses_after": "0.00"}
      ],
      "calculation": [
        "T-01先清费用1680.00元及利息227790×23.5%×70/365＝10266.152054…元，余款清本金。",
        "末段利息＝152860.880953…×13%×26/365＝1415.533637…元。",
        "截日整个C关系余额＝152860.88＋1415.53＋0.00＝154276.41元。"
      ]
    },
    "C_guarantee_and_SP01": {
      "facts": ["dossier.md S06", "dossier.md S10", "dossier.md S13", "dossier.md S14"],
      "rules": [
        {"source_id": "civil-code-2020", "provision": "560、561、687、691、692、693、1260"},
        {"source_id": "guarantee-2020", "provision": "25、31、34"}
      ],
      "explanation": [
        "己的保证订立于2022年，不能随2019年借款适用旧保证规则。“不能履行、无力偿还时才清偿”构成一般保证。未约定期间，故自C到期日2022-12-15起六个月，至2023-06-15届满。",
        "C-诉1撤诉后，甲已于2023-06-14在期间内重新起诉乙，故己不能以期间经过主张免责。仅向己催告不能替代起诉乙；2023-06-25仅确认收件亦不构成新保证。",
        "SP-01于09:20到账时，B、C均已到期，戊、庚和己的保证均依法存续、足额且同等资信。己享有先诉抗辩不等于C没有担保。",
        "依S13双方附件，按付款日可强制请求的年利率比较：B为13.2%，C为13%，故25000.00元全部抵充B，不抵充A或C。B内部先抵利息再抵本金。",
        "S14于13:40签署，不能倒改09:20已完成的抵充。签署前己虽有有效一般保证，但因主债务尚未审判、执行且无先诉抗辩例外，当时亦不能要求其立即清偿。"
      ]
    },
    "C_transfer_and_final_totals": {
      "facts": ["dossier.md S12", "dossier.md S13", "dossier.md S14"],
      "rules": [
        {"source_id": "civil-code-2020", "provision": "552、697"},
        {"source_id": "guarantee-2020", "provision": "36"}
      ],
      "explanation": [
        "三方正文明确SP-01结算后的C尚欠全部由辛独自履行，甲不再向乙请求、乙不再负付款义务。这是全部免责债务承担，不是保证，也不是第552条所称与原债务人并存的债务加入；不能仅凭“代偿”标题定性。",
        "己未书面同意该债务转移，也无另行约定，依第697条对全部转移债务不再承担保证责任。其最终免责原因是债务转移，而非保证期间失权。",
        "S14未改变原到期日，未发生新交付或后续付款。辛直接承担已到期的全部C余额，本次立即给付支持154276.41元；乙在C关系中剩余付款责任为0.00元。正文转移全部余额，不适用共同条款中关于50%份额的计算。"
      ],
      "calculation": [
        "辛立即付款上限＝C本金152860.88＋利息1415.53＋费用0.00＝154276.41元。",
        "乙最终付款总额＝A返还122816.00＋B余额203220.81＋C剩余本人责任0.00＝326036.81元。",
        "戊、庚对B的保证给付额及辛承担的C债务，均不重复计入乙的付款总额。"
      ]
    }
  }
}
